static const lv_image_dsc_t s_not_available_48 = {
    .header = {
        .magic = LV_IMAGE_HEADER_MAGIC,
        .cf = LV_COLOR_FORMAT_ARGB8888,
        .w = 48, .h = 48, .stride = 192U,
    },
    .data_size = sizeof(s_not_available_48_pixels), .data = s_not_available_48_pixels,
};

static const lv_image_dsc_t *image_by_size(const lv_image_dsc_t *small,
                                                const lv_image_dsc_t *large,
                                                uint8_t size)
{
    return size >= NP_WEATHER_STATIC_ICON_LARGE ? large : small;
}

const lv_image_dsc_t *np_weather_static_condition_icon(
    weather_condition_t condition, bool is_day, uint8_t size)
{
    const bool night = !is_day;
    switch (condition) {
    case WEATHER_CONDITION_CLEAR:
        return night ? image_by_size(&s_clear_night_32,
                                      &s_clear_night_48, size)
                     : image_by_size(&s_clear_day_32,
                                      &s_clear_day_48, size);
    case WEATHER_CONDITION_PARTLY_CLOUDY:
        return night ? image_by_size(&s_partly_cloudy_night_32,
                                      &s_partly_cloudy_night_48, size)
                     : image_by_size(&s_partly_cloudy_day_32,
                                      &s_partly_cloudy_day_48, size);
    case WEATHER_CONDITION_FOG:
        return night ? image_by_size(&s_fog_night_32,
                                      &s_fog_night_48, size)
                     : image_by_size(&s_fog_day_32,
                                      &s_fog_day_48, size);
    case WEATHER_CONDITION_DRIZZLE:
        return night ? image_by_size(&s_partly_cloudy_night_drizzle_32,
                                      &s_partly_cloudy_night_drizzle_48, size)
                     : image_by_size(&s_partly_cloudy_day_drizzle_32,
                                      &s_partly_cloudy_day_drizzle_48, size);
    case WEATHER_CONDITION_RAIN:
        return night ? image_by_size(&s_partly_cloudy_night_rain_32,
                                      &s_partly_cloudy_night_rain_48, size)
                     : image_by_size(&s_partly_cloudy_day_rain_32,
                                      &s_partly_cloudy_day_rain_48, size);
    case WEATHER_CONDITION_SNOW:
        return night ? image_by_size(&s_partly_cloudy_night_snow_32,
                                      &s_partly_cloudy_night_snow_48, size)
                     : image_by_size(&s_partly_cloudy_day_snow_32,
                                      &s_partly_cloudy_day_snow_48, size);
    case WEATHER_CONDITION_RAIN_SHOWERS:
        return night ? image_by_size(&s_overcast_night_rain_32,
                                      &s_overcast_night_rain_48, size)
                     : image_by_size(&s_overcast_day_rain_32,
                                      &s_overcast_day_rain_48, size);
    case WEATHER_CONDITION_SNOW_SHOWERS:
        return night ? image_by_size(&s_overcast_night_snow_32,
                                      &s_overcast_night_snow_48, size)
                     : image_by_size(&s_overcast_day_snow_32,
                                      &s_overcast_day_snow_48, size);
    case WEATHER_CONDITION_THUNDERSTORM:
        return night ? image_by_size(&s_thunderstorms_night_rain_32,
                                      &s_thunderstorms_night_rain_48, size)
                     : image_by_size(&s_thunderstorms_day_rain_32,
                                      &s_thunderstorms_day_rain_48, size);
    case WEATHER_CONDITION_VARIABLE:
        return night ? image_by_size(&s_overcast_night_32,
                                      &s_overcast_night_48, size)
                     : image_by_size(&s_overcast_day_32,
                                      &s_overcast_day_48, size);
    default:
        return image_by_size(&s_overcast_day_32, &s_overcast_day_48, size);
    }
}

const lv_image_dsc_t *np_weather_static_info_icon(
    np_weather_static_info_icon_t icon, uint8_t size)
{
    switch (icon) {
    case NP_WEATHER_STATIC_SUNRISE:
        return image_by_size(&s_clear_day_32,
                              &s_clear_day_48, size);
    case NP_WEATHER_STATIC_SUNSET:
        return image_by_size(&s_clear_night_32,
                              &s_clear_night_48, size);
    case NP_WEATHER_STATIC_WIND:
        return image_by_size(&s_wind_32,
                              &s_wind_48, size);
    case NP_WEATHER_STATIC_HUMIDITY:
        return image_by_size(&s_humidity_32,
                              &s_humidity_48, size);
    case NP_WEATHER_STATIC_UV_INDEX:
        return image_by_size(&s_clear_day_32,
                              &s_clear_day_48, size);
    case NP_WEATHER_STATIC_RAIN:
        return image_by_size(&s_rain_32,
                              &s_rain_48, size);
    default:
        return image_by_size(&s_not_available_32, &s_not_available_48, size);
    }
}
